204	    render(
205	        customSeries: CustomSeriesModel,
206	        ecModel: GlobalModel,
207	        api: ExtensionAPI,
208	        payload: Payload
209	    ): void {
210	
211	        // Clear previously rendered progressive elements.
212	        this._progressiveEls = null;
213	
214	        const oldData = this._data;
215	        const data = customSeries.getData();
216	        const group = this.group;
217	        const renderItem = makeRenderItem(customSeries, data, ecModel, api);
218	
219	        if (!oldData) {
220	            // Previous render is incremental render or first render.
221	            // Needs remove the incremental rendered elements.
222	            group.removeAll();
223	        }
224	
225	        data.diff(oldData)
226	            .add(function (newIdx) {
227	                createOrUpdateItem(
228	                    api, null, newIdx, renderItem(newIdx, payload), customSeries, group,
229	                    data
230	                );
231	            })
232	            .remove(function (oldIdx) {
233	                const el = oldData.getItemGraphicEl(oldIdx);
234	                el && applyLeaveTransition(el, customInnerStore(el).option, customSeries);
235	            })
236	            .update(function (newIdx, oldIdx) {
237	                const oldEl = oldData.getItemGraphicEl(oldIdx);
238	
239	                createOrUpdateItem(
240	                    api, oldEl, newIdx, renderItem(newIdx, payload), customSeries, group,
241	                    data
242	                );
243	            })
244	            .execute();
