246	        // Do clipping
247	        const clipPath = customSeries.get('clip', true)
248	            ? createClipPath(customSeries.coordinateSystem, false, customSeries)
249	            : null;
250	        if (clipPath) {
251	            group.setClipPath(clipPath);
