322	function createEl(elOption: CustomElementOption): Element {
323	    const graphicType = elOption.type;
324	    let el;
325	
326	    // Those graphic elements are not shapes. They should not be
327	    // overwritten by users, so do them first.
328	    if (graphicType === 'path') {
329	        const shape = (elOption as CustomSVGPathOption).shape;
330	        // Using pathRect brings convenience to users sacle svg path.
331	        const pathRect = (shape.width != null && shape.height != null)
332	            ? {
333	                x: shape.x || 0,
334	                y: shape.y || 0,
335	                width: shape.width,
336	                height: shape.height
337	            } as RectLike
338	            : null;
339	        const pathData = getPathData(shape);
340	        // Path is also used for icon, so layout 'center' by default.
341	        el = graphicUtil.makePath(pathData, null, pathRect, shape.layout || 'center');
342	        customInnerStore(el).customPathData = pathData;
343	    }
344	    else if (graphicType === 'image') {
345	        el = new graphicUtil.Image({});
346	        customInnerStore(el).customImagePath = (elOption as CustomImageOption).style.image;
347	    }
348	    else if (graphicType === 'text') {
349	        el = new graphicUtil.Text({});
350	        // customInnerStore(el).customText = (elOption.style as TextStyleProps).text;
351	    }
352	    else if (graphicType === 'group') {
353	        el = new graphicUtil.Group();
354	    }
355	    else if (graphicType === 'compoundPath') {
356	        const shape = (elOption as CustomCompoundPathOption).shape;
357	        if (!shape || !shape.paths) {
358	            let errMsg = '';
359	            if (__DEV__) {
360	                errMsg = 'shape.paths must be specified in compoundPath';
361	            }
362	            throwError(errMsg);
363	        }
364	        const paths = map(shape.paths as Path[], function (path) {
365	            if (path.type === 'path') {
366	                return graphicUtil.makePath(path.shape.pathData, path, null);
367	            }
368	            const Clz = graphicUtil.getShapeClass(path.type);
369	            if (!Clz) {
370	                if (typeof path.buildPath === 'function') {
371	                    return path;
372	                }
373	                let errMsg = '';
374	                if (__DEV__) {
375	                    errMsg = 'graphic type "' + graphicType + '" can not be found.';
376	                }
377	                throwError(errMsg);
378	            }
379	            return new Clz();
380	        });
381	        el = new graphicUtil.CompoundPath({
382	            shape: {
383	                paths
384	            }
385	        });
386	    }
387	    else {
388	        const Clz = graphicUtil.getShapeClass(graphicType);
389	        if (!Clz) {
390	            let errMsg = '';
391	            if (__DEV__) {
392	                errMsg = 'graphic type "' + graphicType + '" can not be found.';
393	            }
394	            throwError(errMsg);
395	        }
396	        el = new Clz();
397	    }
398	
399	    customInnerStore(el).customGraphicType = graphicType;
400	    el.name = elOption.name;
401	
402	    // Compat ec4: the default z2 lift is 1. If changing the number,
403	    // some cases probably be broken: hierarchy layout along z, like circle packing,
404	    // where emphasis only intending to modify color/border rather than lift z2.
405	    (el as ECElement).z2EmphasisLift = 1;
406	    (el as ECElement).z2SelectLift = 1;
407	
408	    return el;
