469	function updateElNormal(
470	    // Can be null/undefined
471	    api: ExtensionAPI,
472	    el: Element,
473	    dataIndex: number,
474	    elOption: CustomElementOption,
475	    attachedTxInfo: AttachedTxInfo,
476	    seriesModel: CustomSeriesModel,
477	    isInit: boolean
478	): void {
479	
480	    // Stop and restore before update any other attributes.
481	    stopPreviousKeyframeAnimationAndRestore(el);
482	
483	    const txCfgOpt = attachedTxInfo && attachedTxInfo.normal.cfg;
484	    if (txCfgOpt) {
485	        // PENDING: whether use user object directly rather than clone?
486	        // TODO:5.0 textConfig transition animation?
487	        el.setTextConfig(txCfgOpt);
488	    }
489	
490	    // Default transition ['x', 'y']
491	    if (elOption && elOption.transition == null) {
492	        elOption.transition = DEFAULT_TRANSITION;
493	    }
494	
495	    // Do some normalization on style.
496	    const styleOpt = elOption && (elOption as CustomDisplayableOption).style;
497	
498	    if (styleOpt) {
499	        if (el.type === 'text') {
500	            const textOptionStyle = styleOpt as TextStyleProps;
501	            // Compatible with ec4: if `textFill` or `textStroke` exists use them.
502	            hasOwn(textOptionStyle, 'textFill') && (
503	                textOptionStyle.fill = (textOptionStyle as any).textFill
504	            );
505	            hasOwn(textOptionStyle, 'textStroke') && (
506	                textOptionStyle.stroke = (textOptionStyle as any).textStroke
507	            );
508	        }
509	
510	        let decalPattern;
511	        const decalObj = isPath(el) ? (styleOpt as CustomBaseZRPathOption['style']).decal : null;
512	        if (api && decalObj) {
513	            (decalObj as InnerDecalObject).dirty = true;
514	            decalPattern = createOrUpdatePatternFromDecal(decalObj, api);
515	        }
516	        // Always overwrite in case user specify this prop.
517	        (styleOpt as InnerCustomZRPathOptionStyle).__decalPattern = decalPattern;
518	    }
519	
520	    if (isDisplayable(el)) {
521	        if (styleOpt) {
522	            const decalPattern = (styleOpt as InnerCustomZRPathOptionStyle).__decalPattern;
523	            if (decalPattern) {
524	                (styleOpt as PathStyleProps).decal = decalPattern;
525	            }
526	        }
527	    }
528	
529	    applyUpdateTransition(el, elOption, seriesModel, {
530	        dataIndex,
531	        isInit,
532	        clearStyle: true
533	    });
534	
535	    applyKeyframeAnimation(el, elOption.keyframeAnimation, seriesModel);
536	}
