import { use } from '../src/extension';
import { getCustomSeries } from '../src/chart/custom/customSeriesRegister';
import { CustomSeriesRenderItem } from '../src/chart/custom/CustomSeries';
import { createChart, removeChart } from '../test/ut/core/utHelper';
import { EChartsType } from '../src/echarts.all';

describe('custom-series-installer', function () {

    let chart: EChartsType;
    afterEach(function () {
        removeChart(chart);
        chart = null;
    });

    it('registers a reusable custom series through the standard installer flow', function () {
        const renderItem: CustomSeriesRenderItem = function () {
            return {
                type: 'rect',
                shape: { x: 0, y: 0, width: 10, height: 10 }
            };
        };

        use({
            install: function (registers) {
                expect(typeof registers.registerCustomSeries).toBe('function');
                registers.registerCustomSeries('myReusableSeries', renderItem);
            }
        });

        expect(getCustomSeries('myReusableSeries')).toBe(renderItem);
    });

    it('accepts installer functions as before and existing custom series still renders', function () {
        chart = createChart();
        chart.setOption({
            xAxis: { data: ['a', 'b'] },
            yAxis: {},
            series: [{
                type: 'custom',
                renderItem: function (params, api) {
                    return {
                        type: 'circle',
                        shape: {
                            cx: api.value(0),
                            cy: api.value(1),
                            r: 10
                        }
                    };
                },
                data: [[0, 10], [1, 20]]
            }]
        });

        const el = chart.getZr().storage.getDisplayList().filter(function (el) {
            return el.type === 'circle';
        });
        expect(el.length).toBe(2);
    });
});
